  return begin_transaction()
      .and_then([&](auto&&) { return prepare_statement(_write_stmt); })
      .transform([&](auto&& _stmt) {
        stmt_ = _stmt;
        return Nothing{};
      })
      .or_else([&](auto&& _err) {
        rollback();
        return error(_err.what());
      });
}

