      const Credentials& _credentials) noexcept;

  ~Connection() = default;

  Result<Nothing> begin_transaction() noexcept {
    return execute("START TRANSACTION;");
  }

  Result<Nothing> commit() noexcept { return execute("COMMIT;"); }

