  Result<Nothing> begin_transaction() noexcept;

  Result<Nothing> commit() noexcept;

  Result<Nothing> execute(const std::string& _sql) noexcept {
    return exec(conn_, _sql).transform([](auto&&) { return Nothing{}; });
  }

