        if (res != SQLITE_OK) {
          return error(sqlite3_errmsg(conn_.get()));
        }
      } else {
        const auto res = sqlite3_bind_null(_stmt, i + 1);
        if (res != SQLITE_OK) {
          return error(sqlite3_errmsg(conn_.get()));
        }
