    auto res = sqlite3_step(_stmt);
    if (res != SQLITE_OK && res != SQLITE_ROW && res != SQLITE_DONE) {
      return error(sqlite3_errmsg(conn_.get()));
    }

    res = sqlite3_reset(_stmt);
    if (res != SQLITE_OK) {
      return error(sqlite3_errmsg(conn_.get()));
    }
  }

  const auto res = sqlite3_clear_bindings(_stmt);
  if (res != SQLITE_OK) {
    return error(sqlite3_errmsg(conn_.get()));
  }

  return Nothing{};
