Result<Nothing> Connection::insert_impl(
    const dynamic::Insert& _stmt,
    const std::vector<std::vector<std::optional<std::string>>>&
        _data) noexcept {
  const auto sql = to_sql_impl(_stmt);
  return prepare_statement(sql).and_then(
